`timescale 1 ps / 1 ps

`celldefine

module BFR_FT #(
`ifdef XIL_TIMING
  parameter LOC = "UNPLACED",
`endif
  parameter real ACTIVE_DUTYCYCLE = 100.000,
  parameter FT_MODE = "STREAMING",
  parameter MAX_POINT_SIZE = "4096",
  parameter integer REORDER_EN = 0,
  parameter integer SCALING_EN = 0,
  parameter integer SPARE = 0,
  parameter real TOGGLE_RATE = 100.000,
  parameter integer XPA_CFG0 = 0
)(
  output [495:0] IF_M_AXIS_DOUT_TDATA,
  output IF_M_AXIS_DOUT_TLAST,
  output [107:0] IF_M_AXIS_DOUT_TUSER,
  output IF_M_AXIS_DOUT_TVALID,
  output IF_S_AXIS_DIN_TREADY,
  output IF_S_AXIS_PH2_CTRL_TREADY,
  output SHUTDOWN_OUT,
  output [9:0] STATUS,
  output [14:0] STATUS_DBL,

  input CLK,
  input [15:0] CLK_IO,
  input [127:0] CTRL,
  input [13:0] CTRL_DBL,
  input D_CLK,
  input [6:0] EMA,
  input ENABLE,
  input [14:0] FABRIC_CNTL_IN,
  input IF_M_AXIS_DOUT_TREADY,
  input [287:0] IF_S_AXIS_DIN_TDATA,
  input IF_S_AXIS_DIN_TLAST,
  input [37:0] IF_S_AXIS_DIN_TUSER,
  input IF_S_AXIS_DIN_TVALID,
  input [123:0] IF_S_AXIS_PH2_CTRL_TDATA,
  input IF_S_AXIS_PH2_CTRL_TLAST,
  input IF_S_AXIS_PH2_CTRL_TVALID,
  input RESET_N,
  input SHUTDOWN_IN,
  input [7:0] STATIC_CTRL
);

// define constants
  localparam MODULE_NAME = "BFR_FT";
  
  reg trig_attr;
// include dynamic registers - XILINX test only
`ifdef XIL_DR
  `include "BFR_FT_dr.v"
`else
  real ACTIVE_DUTYCYCLE_REG = ACTIVE_DUTYCYCLE;
  reg [88:1] FT_MODE_REG = FT_MODE;
  reg [32:1] MAX_POINT_SIZE_REG = MAX_POINT_SIZE;
  reg [0:0] REORDER_EN_REG = REORDER_EN;
  reg [0:0] SCALING_EN_REG = SCALING_EN;
  reg [9:0] SPARE_REG = SPARE;
  real TOGGLE_RATE_REG = TOGGLE_RATE;
  reg [15:0] XPA_CFG0_REG = XPA_CFG0;
`endif

`ifdef XIL_XECLIB
  wire [63:0] ACTIVE_DUTYCYCLE_BIN;
  wire [63:0] TOGGLE_RATE_BIN;
`else
  reg [63:0] ACTIVE_DUTYCYCLE_BIN;
  reg [63:0] TOGGLE_RATE_BIN;
`endif

`ifdef XIL_XECLIB
reg glblGSR = 1'b0;
`else
tri0 glblGSR = glbl.GSR;
`endif

  wire IF_M_AXIS_DOUT_TLAST_out;
  wire IF_M_AXIS_DOUT_TVALID_out;
  wire IF_S_AXIS_DIN_TREADY_out;
  wire IF_S_AXIS_PH2_CTRL_TREADY_out;
  wire SCAN_CNTRL_CHNL_OUT_EXT_out;
  wire SHUTDOWN_OUT_out;
  wire TEST_PIN_CHAR_OUT_out;
  wire [107:0] IF_M_AXIS_DOUT_TUSER_out;
  wire [14:0] STATUS_DBL_out;
  wire [1:0] SCAN_CHNL_OUT_EXT_out;
  wire [495:0] IF_M_AXIS_DOUT_TDATA_out;
  wire [9:0] STATUS_out;

  wire CLK_in;
  wire D_CLK_in;
  wire ENABLE_in;
  wire IF_M_AXIS_DOUT_TREADY_in;
  wire IF_S_AXIS_DIN_TLAST_in;
  wire IF_S_AXIS_DIN_TVALID_in;
  wire IF_S_AXIS_PH2_CTRL_TLAST_in;
  wire IF_S_AXIS_PH2_CTRL_TVALID_in;
  wire REG_CACHE_CLR_N_in;
  wire RESET_N_in;
  wire SCAN_CLK_N_IN_EXT_in;
  wire SCAN_CNTRL_CHNL_IN_EXT_in;
  wire SCAN_EDT_UPDT_N_IN_EXT_in;
  wire SCAN_EN_N_IN_EXT_in;
  wire SCAN_MODE_RST_N_IN_EXT_in;
  wire SHUTDOWN_IN_in;
  wire TEST_BYPASS_N_in;
  wire TEST_CSSD_TRIG_N_in;
  wire TEST_PIN_CHAR_IN_in;
  wire [123:0] IF_S_AXIS_PH2_CTRL_TDATA_in;
  wire [127:0] CTRL_in;
  wire [13:0] CTRL_DBL_in;
  wire [14:0] FABRIC_CNTL_IN_in;
  wire [15:0] CLK_IO_in;
  wire [1:0] SCAN_CHNL_IN_EXT_in;
  wire [287:0] IF_S_AXIS_DIN_TDATA_in;
  wire [37:0] IF_S_AXIS_DIN_TUSER_in;
  wire [6:0] EMA_in;
  wire [7:0] STATIC_CTRL_in;

`ifdef XIL_TIMING
  wire CLK_delay;
  wire ENABLE_delay;
  wire IF_M_AXIS_DOUT_TREADY_delay;
  wire IF_S_AXIS_DIN_TLAST_delay;
  wire IF_S_AXIS_DIN_TVALID_delay;
  wire IF_S_AXIS_PH2_CTRL_TLAST_delay;
  wire IF_S_AXIS_PH2_CTRL_TVALID_delay;
  wire RESET_N_delay;
  wire [123:0] IF_S_AXIS_PH2_CTRL_TDATA_delay;
  wire [15:0] CLK_IO_delay;
  wire [287:0] IF_S_AXIS_DIN_TDATA_delay;
  wire [37:0] IF_S_AXIS_DIN_TUSER_delay;
`endif

  
  assign IF_M_AXIS_DOUT_TDATA = IF_M_AXIS_DOUT_TDATA_out;
  assign IF_M_AXIS_DOUT_TLAST = IF_M_AXIS_DOUT_TLAST_out;
  assign IF_M_AXIS_DOUT_TUSER = IF_M_AXIS_DOUT_TUSER_out;
  assign IF_M_AXIS_DOUT_TVALID = IF_M_AXIS_DOUT_TVALID_out;
  assign IF_S_AXIS_DIN_TREADY = IF_S_AXIS_DIN_TREADY_out;
  assign IF_S_AXIS_PH2_CTRL_TREADY = IF_S_AXIS_PH2_CTRL_TREADY_out;
  assign SHUTDOWN_OUT = SHUTDOWN_OUT_out;
  assign STATUS = STATUS_out;
  assign STATUS_DBL = STATUS_DBL_out;

`ifdef XIL_TIMING
  assign CLK_IO_in[13] = CLK_IO_delay[13];
  assign CLK_IO_in[2] = CLK_IO_delay[2];
  assign CLK_IO_in[5] = CLK_IO_delay[5];
  assign CLK_IO_in[9] = CLK_IO_delay[9];
  assign CLK_in = CLK_delay;
  assign ENABLE_in = ENABLE_delay;
  assign IF_M_AXIS_DOUT_TREADY_in = IF_M_AXIS_DOUT_TREADY_delay;
  assign IF_S_AXIS_DIN_TDATA_in = IF_S_AXIS_DIN_TDATA_delay;
  assign IF_S_AXIS_DIN_TLAST_in = IF_S_AXIS_DIN_TLAST_delay;
  assign IF_S_AXIS_DIN_TUSER_in = IF_S_AXIS_DIN_TUSER_delay;
  assign IF_S_AXIS_DIN_TVALID_in = IF_S_AXIS_DIN_TVALID_delay;
  assign IF_S_AXIS_PH2_CTRL_TDATA_in = IF_S_AXIS_PH2_CTRL_TDATA_delay;
  assign IF_S_AXIS_PH2_CTRL_TLAST_in = IF_S_AXIS_PH2_CTRL_TLAST_delay;
  assign IF_S_AXIS_PH2_CTRL_TVALID_in = IF_S_AXIS_PH2_CTRL_TVALID_delay;
  assign RESET_N_in = RESET_N_delay;
`else
  assign CLK_IO_in[13] = CLK_IO[13];
  assign CLK_IO_in[2] = CLK_IO[2];
  assign CLK_IO_in[5] = CLK_IO[5];
  assign CLK_IO_in[9] = CLK_IO[9];
  assign CLK_in = CLK;
  assign ENABLE_in = ENABLE;
  assign IF_M_AXIS_DOUT_TREADY_in = IF_M_AXIS_DOUT_TREADY;
  assign IF_S_AXIS_DIN_TDATA_in = IF_S_AXIS_DIN_TDATA;
  assign IF_S_AXIS_DIN_TLAST_in = IF_S_AXIS_DIN_TLAST;
  assign IF_S_AXIS_DIN_TUSER_in = IF_S_AXIS_DIN_TUSER;
  assign IF_S_AXIS_DIN_TVALID_in = IF_S_AXIS_DIN_TVALID;
  assign IF_S_AXIS_PH2_CTRL_TDATA_in = IF_S_AXIS_PH2_CTRL_TDATA;
  assign IF_S_AXIS_PH2_CTRL_TLAST_in = IF_S_AXIS_PH2_CTRL_TLAST;
  assign IF_S_AXIS_PH2_CTRL_TVALID_in = IF_S_AXIS_PH2_CTRL_TVALID;
  assign RESET_N_in = RESET_N;
`endif

  assign CLK_IO_in[0] = CLK_IO[0];
  assign CLK_IO_in[10] = CLK_IO[10];
  assign CLK_IO_in[11] = CLK_IO[11];
  assign CLK_IO_in[12] = CLK_IO[12];
  assign CLK_IO_in[14] = CLK_IO[14];
  assign CLK_IO_in[15] = CLK_IO[15];
  assign CLK_IO_in[1] = CLK_IO[1];
  assign CLK_IO_in[3] = CLK_IO[3];
  assign CLK_IO_in[4] = CLK_IO[4];
  assign CLK_IO_in[6] = CLK_IO[6];
  assign CLK_IO_in[7] = CLK_IO[7];
  assign CLK_IO_in[8] = CLK_IO[8];
  assign CTRL_DBL_in = CTRL_DBL;
  assign CTRL_in = CTRL;
  assign D_CLK_in = D_CLK;
  assign EMA_in = EMA;
  assign FABRIC_CNTL_IN_in = FABRIC_CNTL_IN;
  assign SHUTDOWN_IN_in = SHUTDOWN_IN;
  assign STATIC_CTRL_in = STATIC_CTRL;

`ifndef XIL_XECLIB
  reg attr_test;
  reg attr_err;
  
  initial begin
  trig_attr = 1'b0;
  `ifdef XIL_ATTR_TEST
    attr_test = 1'b1;
  `else
    attr_test = 1'b0;
  `endif
    attr_err = 1'b0;
    #1;
    trig_attr = ~trig_attr;
  end
`endif

`ifdef XIL_XECLIB
  assign ACTIVE_DUTYCYCLE_BIN = ACTIVE_DUTYCYCLE_REG * 1000;
  
  assign TOGGLE_RATE_BIN = TOGGLE_RATE_REG * 1000;
  
`else
  always @ (trig_attr) begin
  #1;
  ACTIVE_DUTYCYCLE_BIN = ACTIVE_DUTYCYCLE_REG * 1000;
  
  TOGGLE_RATE_BIN = TOGGLE_RATE_REG * 1000;
  
  end
`endif

`ifndef XIL_XECLIB
  always @ (trig_attr) begin
    #1;
    if ((attr_test == 1'b1) ||
        (ACTIVE_DUTYCYCLE_REG < 0.000 || ACTIVE_DUTYCYCLE_REG > 100.000)) begin
      $display("Error: [Unisim %s-101] ACTIVE_DUTYCYCLE attribute is set to %f.  Legal values for this attribute are 0.000 to 100.000. Instance: %m", MODULE_NAME, ACTIVE_DUTYCYCLE_REG);
      attr_err = 1'b1;
    end
    
    if ((attr_test == 1'b1) ||
        ((FT_MODE_REG != "STREAMING") &&
         (FT_MODE_REG != "MEMORY ONLY"))) begin
      $display("Error: [Unisim %s-102] FT_MODE attribute is set to %s.  Legal values for this attribute are STREAMING or MEMORY ONLY. Instance: %m", MODULE_NAME, FT_MODE_REG);
      attr_err = 1'b1;
    end
    
    if ((attr_test == 1'b1) ||
        ((MAX_POINT_SIZE_REG != "4096") &&
         (MAX_POINT_SIZE_REG != "8") &&
         (MAX_POINT_SIZE_REG != "16") &&
         (MAX_POINT_SIZE_REG != "32") &&
         (MAX_POINT_SIZE_REG != "64") &&
         (MAX_POINT_SIZE_REG != "128") &&
         (MAX_POINT_SIZE_REG != "256") &&
         (MAX_POINT_SIZE_REG != "512") &&
         (MAX_POINT_SIZE_REG != "1024") &&
         (MAX_POINT_SIZE_REG != "2048"))) begin
      $display("Error: [Unisim %s-103] MAX_POINT_SIZE attribute is set to %s.  Legal values for this attribute are 4096, 8, 16, 32, 64, 128, 256, 512, 1024 or 2048. Instance: %m", MODULE_NAME, MAX_POINT_SIZE_REG);
      attr_err = 1'b1;
    end
    
    if ((attr_test == 1'b1) ||
        ((REORDER_EN_REG < 0) || (REORDER_EN_REG > 1))) begin
      $display("Error: [Unisim %s-104] REORDER_EN attribute is set to %d.  Legal values for this attribute are 0 to 1. Instance: %m", MODULE_NAME, REORDER_EN_REG);
      attr_err = 1'b1;
    end
    
    if ((attr_test == 1'b1) ||
        ((SCALING_EN_REG < 0) || (SCALING_EN_REG > 1))) begin
      $display("Error: [Unisim %s-105] SCALING_EN attribute is set to %d.  Legal values for this attribute are 0 to 1. Instance: %m", MODULE_NAME, SCALING_EN_REG);
      attr_err = 1'b1;
    end
    
    if ((attr_test == 1'b1) ||
        ((SPARE_REG < 0) || (SPARE_REG > 1023))) begin
      $display("Error: [Unisim %s-106] SPARE attribute is set to %d.  Legal values for this attribute are 0 to 1023. Instance: %m", MODULE_NAME, SPARE_REG);
      attr_err = 1'b1;
    end
    
    if ((attr_test == 1'b1) ||
        (TOGGLE_RATE_REG < 0.000 || TOGGLE_RATE_REG > 100.000)) begin
      $display("Error: [Unisim %s-107] TOGGLE_RATE attribute is set to %f.  Legal values for this attribute are 0.000 to 100.000. Instance: %m", MODULE_NAME, TOGGLE_RATE_REG);
      attr_err = 1'b1;
    end
    
    if ((attr_test == 1'b1) ||
        ((XPA_CFG0_REG < 0) || (XPA_CFG0_REG > 65535))) begin
      $display("Error: [Unisim %s-108] XPA_CFG0 attribute is set to %d.  Legal values for this attribute are 0 to 65535. Instance: %m", MODULE_NAME, XPA_CFG0_REG);
      attr_err = 1'b1;
    end
    
    if (attr_err == 1'b1) #1 $finish;
  end
`endif



assign REG_CACHE_CLR_N_in = 1'b1; // tie off
assign SCAN_CHNL_IN_EXT_in = 2'b11; // tie off
assign SCAN_CLK_N_IN_EXT_in = 1'b1; // tie off
assign SCAN_CNTRL_CHNL_IN_EXT_in = 1'b1; // tie off
assign SCAN_EDT_UPDT_N_IN_EXT_in = 1'b1; // tie off
assign SCAN_EN_N_IN_EXT_in = 1'b1; // tie off
assign SCAN_MODE_RST_N_IN_EXT_in = 1'b1; // tie off
assign TEST_BYPASS_N_in = 1'b1; // tie off
assign TEST_CSSD_TRIG_N_in = 1'b1; // tie off
assign TEST_PIN_CHAR_IN_in = 1'b1; // tie off

  SIP_BFR_FT SIP_BFR_FT_INST (
    .ACTIVE_DUTYCYCLE (ACTIVE_DUTYCYCLE_BIN),
    .FT_MODE (FT_MODE_REG),
    .MAX_POINT_SIZE (MAX_POINT_SIZE_REG),
    .REORDER_EN (REORDER_EN_REG),
    .SCALING_EN (SCALING_EN_REG),
    .SPARE (SPARE_REG),
    .TOGGLE_RATE (TOGGLE_RATE_BIN),
    .XPA_CFG0 (XPA_CFG0_REG),
    .IF_M_AXIS_DOUT_TDATA (IF_M_AXIS_DOUT_TDATA_out),
    .IF_M_AXIS_DOUT_TLAST (IF_M_AXIS_DOUT_TLAST_out),
    .IF_M_AXIS_DOUT_TUSER (IF_M_AXIS_DOUT_TUSER_out),
    .IF_M_AXIS_DOUT_TVALID (IF_M_AXIS_DOUT_TVALID_out),
    .IF_S_AXIS_DIN_TREADY (IF_S_AXIS_DIN_TREADY_out),
    .IF_S_AXIS_PH2_CTRL_TREADY (IF_S_AXIS_PH2_CTRL_TREADY_out),
    .SCAN_CHNL_OUT_EXT (SCAN_CHNL_OUT_EXT_out),
    .SCAN_CNTRL_CHNL_OUT_EXT (SCAN_CNTRL_CHNL_OUT_EXT_out),
    .SHUTDOWN_OUT (SHUTDOWN_OUT_out),
    .STATUS (STATUS_out),
    .STATUS_DBL (STATUS_DBL_out),
    .TEST_PIN_CHAR_OUT (TEST_PIN_CHAR_OUT_out),
    .CLK (CLK_in),
    .CLK_IO (CLK_IO_in),
    .CTRL (CTRL_in),
    .CTRL_DBL (CTRL_DBL_in),
    .D_CLK (D_CLK_in),
    .EMA (EMA_in),
    .ENABLE (ENABLE_in),
    .FABRIC_CNTL_IN (FABRIC_CNTL_IN_in),
    .IF_M_AXIS_DOUT_TREADY (IF_M_AXIS_DOUT_TREADY_in),
    .IF_S_AXIS_DIN_TDATA (IF_S_AXIS_DIN_TDATA_in),
    .IF_S_AXIS_DIN_TLAST (IF_S_AXIS_DIN_TLAST_in),
    .IF_S_AXIS_DIN_TUSER (IF_S_AXIS_DIN_TUSER_in),
    .IF_S_AXIS_DIN_TVALID (IF_S_AXIS_DIN_TVALID_in),
    .IF_S_AXIS_PH2_CTRL_TDATA (IF_S_AXIS_PH2_CTRL_TDATA_in),
    .IF_S_AXIS_PH2_CTRL_TLAST (IF_S_AXIS_PH2_CTRL_TLAST_in),
    .IF_S_AXIS_PH2_CTRL_TVALID (IF_S_AXIS_PH2_CTRL_TVALID_in),
    .REG_CACHE_CLR_N (REG_CACHE_CLR_N_in),
    .RESET_N (RESET_N_in),
    .SCAN_CHNL_IN_EXT (SCAN_CHNL_IN_EXT_in),
    .SCAN_CLK_N_IN_EXT (SCAN_CLK_N_IN_EXT_in),
    .SCAN_CNTRL_CHNL_IN_EXT (SCAN_CNTRL_CHNL_IN_EXT_in),
    .SCAN_EDT_UPDT_N_IN_EXT (SCAN_EDT_UPDT_N_IN_EXT_in),
    .SCAN_EN_N_IN_EXT (SCAN_EN_N_IN_EXT_in),
    .SCAN_MODE_RST_N_IN_EXT (SCAN_MODE_RST_N_IN_EXT_in),
    .SHUTDOWN_IN (SHUTDOWN_IN_in),
    .STATIC_CTRL (STATIC_CTRL_in),
    .TEST_BYPASS_N (TEST_BYPASS_N_in),
    .TEST_CSSD_TRIG_N (TEST_CSSD_TRIG_N_in),
    .TEST_PIN_CHAR_IN (TEST_PIN_CHAR_IN_in),
    .GSR (glblGSR)
  );

`ifdef XIL_TIMING
  reg notifier;
`endif

`ifndef XIL_XECLIB
  // begin timing section
  specify
    (CLK => IF_M_AXIS_DOUT_TDATA[0]) = (100:100:100, 100:100:100);
    (CLK => IF_M_AXIS_DOUT_TDATA[100]) = (100:100:100, 100:100:100);
    (CLK => IF_M_AXIS_DOUT_TDATA[101]) = (100:100:100, 100:100:100);
    (CLK => IF_M_AXIS_DOUT_TDATA[102]) = (100:100:100, 100:100:100);
    (CLK => IF_M_AXIS_DOUT_TDATA[103]) = (100:100:100, 100:100:100);
    (CLK => IF_M_AXIS_DOUT_TDATA[104]) = (100:100:100, 100:100:100);
    (CLK => IF_M_AXIS_DOUT_TDATA[105]) = (100:100:100, 100:100:100);
    (CLK => IF_M_AXIS_DOUT_TDATA[106]) = (100:100:100, 100:100:100);
    (CLK => IF_M_AXIS_DOUT_TDATA[107]) = (100:100:100, 100:100:100);
    (CLK => IF_M_AXIS_DOUT_TDATA[108]) = (100:100:100, 100:100:100);
    (CLK => IF_M_AXIS_DOUT_TDATA[109]) = (100:100:100, 100:100:100);
    (CLK => IF_M_AXIS_DOUT_TDATA[10]) = (100:100:100, 100:100:100);
    (CLK => IF_M_AXIS_DOUT_TDATA[110]) = (100:100:100, 100:100:100);
    (CLK => IF_M_AXIS_DOUT_TDATA[111]) = (100:100:100, 100:100:100);
    (CLK => IF_M_AXIS_DOUT_TDATA[112]) = (100:100:100, 100:100:100);
    (CLK => IF_M_AXIS_DOUT_TDATA[113]) = (100:100:100, 100:100:100);
    (CLK => IF_M_AXIS_DOUT_TDATA[114]) = (100:100:100, 100:100:100);
    (CLK => IF_M_AXIS_DOUT_TDATA[115]) = (100:100:100, 100:100:100);
    (CLK => IF_M_AXIS_DOUT_TDATA[116]) = (100:100:100, 100:100:100);
    (CLK => IF_M_AXIS_DOUT_TDATA[117]) = (100:100:100, 100:100:100);
    (CLK => IF_M_AXIS_DOUT_TDATA[118]) = (100:100:100, 100:100:100);
    (CLK => IF_M_AXIS_DOUT_TDATA[119]) = (100:100:100, 100:100:100);
    (CLK => IF_M_AXIS_DOUT_TDATA[11]) = (100:100:100, 100:100:100);
    (CLK => IF_M_AXIS_DOUT_TDATA[120]) = (100:100:100, 100:100:100);
    (CLK => IF_M_AXIS_DOUT_TDATA[121]) = (100:100:100, 100:100:100);
    (CLK => IF_M_AXIS_DOUT_TDATA[122]) = (100:100:100, 100:100:100);
    (CLK => IF_M_AXIS_DOUT_TDATA[123]) = (100:100:100, 100:100:100);
    (CLK => IF_M_AXIS_DOUT_TDATA[124]) = (100:100:100, 100:100:100);
    (CLK => IF_M_AXIS_DOUT_TDATA[125]) = (100:100:100, 100:100:100);
    (CLK => IF_M_AXIS_DOUT_TDATA[126]) = (100:100:100, 100:100:100);
    (CLK => IF_M_AXIS_DOUT_TDATA[127]) = (100:100:100, 100:100:100);
    (CLK => IF_M_AXIS_DOUT_TDATA[128]) = (100:100:100, 100:100:100);
    (CLK => IF_M_AXIS_DOUT_TDATA[129]) = (100:100:100, 100:100:100);
    (CLK => IF_M_AXIS_DOUT_TDATA[12]) = (100:100:100, 100:100:100);
    (CLK => IF_M_AXIS_DOUT_TDATA[130]) = (100:100:100, 100:100:100);
    (CLK => IF_M_AXIS_DOUT_TDATA[131]) = (100:100:100, 100:100:100);
    (CLK => IF_M_AXIS_DOUT_TDATA[132]) = (100:100:100, 100:100:100);
    (CLK => IF_M_AXIS_DOUT_TDATA[133]) = (100:100:100, 100:100:100);
    (CLK => IF_M_AXIS_DOUT_TDATA[134]) = (100:100:100, 100:100:100);
    (CLK => IF_M_AXIS_DOUT_TDATA[135]) = (100:100:100, 100:100:100);
    (CLK => IF_M_AXIS_DOUT_TDATA[136]) = (100:100:100, 100:100:100);
    (CLK => IF_M_AXIS_DOUT_TDATA[137]) = (100:100:100, 100:100:100);
    (CLK => IF_M_AXIS_DOUT_TDATA[138]) = (100:100:100, 100:100:100);
    (CLK => IF_M_AXIS_DOUT_TDATA[139]) = (100:100:100, 100:100:100);
    (CLK => IF_M_AXIS_DOUT_TDATA[13]) = (100:100:100, 100:100:100);
